namespace GoGoaRentals.Services.Storage;

/// <summary>Private file storage. Keys are opaque, generated by the store, and never served publicly.</summary>
public interface IFileStorage
{
    Task<string> SaveAsync(string folder, string extension, Stream content, CancellationToken cancellationToken = default);

    /// <summary>Returns null if the key doesn't exist.</summary>
    Stream? OpenRead(string key);

    void Delete(string key);
}
